(7735695, 1275212, 29535, '<td valign="top">The combination of not only the lights and that perfect architecture but also that wonderful driveway make this a really strong ribbon contender. Top 3 for me, it''s like looking at a Hallmark movie set :)</td>', 'The combination of not only the lights and that perfect architecture but also that wonderful driveway make this a really strong ribbon contender. Top 3 for me, it''s like looking at a Hallmark movie set :)', '2022-12-28 07:04:39.000000', NULL, 1),
(7735696, 1275231, 29535, '<td valign="top">Really nice entry. Gorgeous colours and lighting with a great sunset that feels Christmassy in itself. Great job!</td>', 'Really nice entry. Gorgeous colours and lighting with a great sunset that feels Christmassy in itself. Great job!', '2022-12-28 07:05:27.000000', NULL, 1),
(7735697, 1275250, 29535, '<td valign="top">I really feel like this challenge was best approached getting out and shooting the displays in your local town or city and this shot epitomises that. The skyline in the background with the combination of the sea and the high-rises just makes it for me. Great job!</td>', 'I really feel like this challenge was best approached getting out and shooting the displays in your local town or city and this shot epitomises that. The skyline in the background with the combination of the sea and the high-rises just makes it for me. Great job!', '2022-12-28 07:06:40.000000', NULL, 1),
