(7735788, 1275243, 65234, '<td valign="top">I like the little starbursts around some of the white lights. And the owl. It''s a nice owl :-)</td>', 'I like the little starbursts around some of the white lights. And the owl. It''s a nice owl :-)', '2022-12-30 17:53:49.000000', NULL, 1),
(7735789, 1275212, 65234, '<td valign="top">Somebody went to a lot of trouble to set up this display. Quite festive.</td>', 'Somebody went to a lot of trouble to set up this display. Quite festive.', '2022-12-30 17:54:45.000000', NULL, 1),
